"""Editable table layouts transcribed from the supplied NBA Annexure II."""


def _table(key, title, columns, row_labels=(), header_groups=(), row_data=(), fixed_rows=()):
    rows = [list(row) for row in fixed_rows] if fixed_rows else [[label, *([""] * (len(columns) - 1))] for label in row_labels]
    if row_data:
        rows = [list(row) for row in row_data]
    if not rows:
        rows = [[""] * len(columns)]
    normalized_groups = []
    offset = 0
    for group in header_groups:
        item = dict(group)
        if item["span"] == 1 and item["label"] == columns[offset]:
            item["rowspan"] = 2
        if not item.get("rowspan"):
            item["columns"] = columns[offset:offset + item["span"]]
        normalized_groups.append(item)
        offset += item["span"]
    fixed_first_column = bool(fixed_rows or row_data)
    return {"key": f"annexure_{key}", "title": title, "columns": columns, "rows": rows, "header_groups": normalized_groups, "fixed_first_column": fixed_first_column, "allow_add_rows": not fixed_rows and not row_data}


